  "scenario": "A person is interviewing for a job as a lawyer",
  "agents": [
    {
      "name": "Interviewer",
      "role": "Hiring manager",
      "goal": "Assess the candidate's legal knowledge and communication skills",
      "constraints": ["Evaluate based on prepared questions", "Maintain neutrality", "Record responses"]
    },
    {
      "name": "Candidate",
      "role": "Job applicant",
      "goal": "Demonstrate legal expertise and fit for the role",
      "constraints": ["Answer questions without prior knowledge of the interviewer's questions", "Respond within 30 seconds", "Avoid jargon"]
    },
    {
      "name": "Note-Taker",
      "role": "Assistant",
      "goal": "Accurately record the interview for later review",
      "constraints": ["Write without interrupting", "Focus on key points", "Use shorthand if needed"]
    }
  ],
  "outcome": {
    "name": "Interview success",
    "operationalization": "The interviewer's assessment of the candidate's suitability for the role",
    "measurement_question": "How would the interviewer rate the candidate's performance on a scale of 1 to 10?",
    "respondent": "Interviewer"
  },
  "causes": [
    {
      "name": "Legal knowledge",
      "hypothesis": "Candidates with stronger legal knowledge will perform better in the interview",
      "predicted_direction": "increase",
      "treatment_values": ["Knowledge of contract law", "Knowledge of criminal law", "Knowledge of corporate law"]
    },
    {
      "name": "Communication clarity",
      "hypothesis": "Candidates who communicate more clearly will be rated higher",
      "predicted_direction": "increase",
      "treatment_values": ["Clear and concise", "Somewhat clear", "Unclear and verbose"]
    },
    {
      "name": "Confidence level",
      "hypothesis": "Higher confidence will lead to better performance",
      "predicted_direction": "increase",
      "treatment_values": ["High confidence", "Moderate confidence", "Low confidence"]
    }
  ],
  "information_scope": {
    "public": ["Interview questions", "Candidate's answers", "Note-taker's summary"],
    "private": [
      {
        "agent": "Interviewer",
        "information": ["Personal bias", "Previous experience with candidates", "Job requirements"]
      },
      {
        "agent": "Candidate",
        "information": ["Interviewer's past interviews", "Company's legal history", "Note-taker's notes"]
      },
      {
        "agent": "Note-Taker",
        "information": ["Interviewer's notes", "Candidate's body language", "Previous interviews"]
      }
    ]
  },
  "interaction": {
    "order": ["Interviewer", "Candidate", "Note-Taker"],
    "max_turns": 3,
    "stopping_rule": "After the candidate answers all questions and the note-taker summarizes the interview"
  }
}

